config.script:
// Redirect to consent service
var consentUrl = 'http://consent-service:8900/consent';
var params = new URLSearchParams();
params.append('access_token', context.getToken().getToken());
params.append('user_id', user.getId());
params.append('redirect_uri', authenticationSession.getRedirectUri());

// Store in session note for later retrieval
authenticationSession.setAuthNote('consent_redirect', consentUrl + '?' + params.toString());

// Redirect
context.redirect(consentUrl + '?' + params.toString());
